@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class PersonalAccount {
}

class BusinessAccount {
  + CompanyName : string
  + MonthlyFee : double
}

class Page {
  + PageName : string
  + VisitCount : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

class FriendRequest {
}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
PersonalAccount --|> Account
BusinessAccount --|> Account

Account "1" *-- "*" Page
BusinessAccount "1" -- "*" AdvertisementPage
AdvertisementPage --|> Page

PersonalAccount "0..1" -- "0..1" PersonalAccount : friend
PersonalAccount "1" -- "*" FriendRequest
PersonalAccount "1" -- "*" Page : privilege

@enduml

